using System.Reflection;

public class Container
{
    private enum Life { Singleton, Transient }
    private sealed record Registration(Type Impl, Life Life);

    private readonly Dictionary<Type, Registration> _registrations = new();
    private readonly Dictionary<Type, object> _singletons = new();

    public void AddSingleton<TService, TImpl>() where TImpl : TService => Register(typeof(TService), typeof(TImpl), Life.Singleton);
    public void AddTransient<TService, TImpl>() where TImpl : TService => Register(typeof(TService), typeof(TImpl), Life.Transient);

    public void AddInstance<TService>(TService instance) where TService : notnull
    {
        _registrations[typeof(TService)] = new Registration(instance.GetType(), Life.Singleton);
        _singletons[typeof(TService)] = instance;
    }

    private void Register(Type service, Type impl, Life life)
    {
        _registrations[service] = new Registration(impl, life);
        _singletons.Remove(service);
    }

    public T Resolve<T>() => (T)Resolve(typeof(T), new List<Type>());

    private object Resolve(Type service, List<Type> chain)
    {
        if (chain.Contains(service))
            throw new InvalidOperationException("circular dependency: " + string.Join(" -> ", chain.Append(service).Select(t => t.Name)));
        if (!_registrations.TryGetValue(service, out var reg))
            throw new InvalidOperationException($"no registration for {service.Name}");
        if (reg.Life == Life.Singleton && _singletons.TryGetValue(service, out var existing)) return existing;

        chain.Add(service);
        ConstructorInfo ctor = reg.Impl.GetConstructors().OrderByDescending(c => c.GetParameters().Length).First();
        object[] args = ctor.GetParameters().Select(p => Resolve(p.ParameterType, chain)).ToArray();
        chain.RemoveAt(chain.Count - 1);

        object created = ctor.Invoke(args);
        if (reg.Life == Life.Singleton) _singletons[service] = created;
        return created;
    }
}

