Test("building a graph", () =>
{
    var c = new Container();
    c.AddInstance<IClock>(new FixedClock(new DateTime(2026, 3, 14, 9, 0, 0)));
    c.AddTransient<IGreeter, Greeter>();
    c.AddTransient<Reception, Reception>();
    var r = c.Resolve<Reception>();
    CheckEq(r.Welcome("Ada"), "Good morning, Ada");
});

Test("lifetimes", () =>
{
    var c = new Container();
    c.AddSingleton<Counter, Counter>();
    c.AddTransient<IGreeter, Greeter>();
    c.AddInstance<IClock>(new FixedClock(DateTime.MinValue));
    Check(ReferenceEquals(c.Resolve<Counter>(), c.Resolve<Counter>()), "a singleton is reused");
    Check(!ReferenceEquals(c.Resolve<IGreeter>(), c.Resolve<IGreeter>()), "a transient is new every time");
    var clock = c.Resolve<IClock>();
    Check(ReferenceEquals(clock, c.Resolve<IClock>()), "an instance is always the same object");
});

Test("the constructor with the most parameters", () =>
{
    var c = new Container();
    c.AddInstance<IClock>(new FixedClock(new DateTime(2026, 1, 1, 20, 0, 0)));
    c.AddSingleton<Counter, Counter>();
    c.AddTransient<Report, Report>();
    CheckEq(c.Resolve<Report>().Describe(), "2026-01-01 with counter");
});

Test("replacing a registration", () =>
{
    var c = new Container();
    c.AddInstance<IClock>(new FixedClock(new DateTime(2026, 1, 1, 9, 0, 0)));
    c.AddInstance<IClock>(new FixedClock(new DateTime(2026, 1, 1, 21, 0, 0)));
    c.AddTransient<IGreeter, Greeter>();
    CheckEq(c.Resolve<IGreeter>().Greet("Bo"), "Good evening, Bo");
});

Test("errors", () =>
{
    var c = new Container();
    c.AddTransient<IGreeter, Greeter>();
    try { c.Resolve<IGreeter>(); Check(false, "should throw"); }
    catch (InvalidOperationException e) { CheckEq(e.Message, "no registration for IClock"); }
    c.AddTransient<Ping, Ping>();
    c.AddTransient<Pong, Pong>();
    try { c.Resolve<Ping>(); Check(false, "should throw"); }
    catch (InvalidOperationException e) { CheckEq(e.Message, "circular dependency: Ping -> Pong -> Ping"); }
});

