public interface IClock { DateTime Now { get; } }
public sealed class FixedClock(DateTime now) : IClock { public DateTime Now => now; }

public interface IGreeter { string Greet(string name); }
public sealed class Greeter(IClock clock) : IGreeter
{
    public string Greet(string name) => (clock.Now.Hour < 12 ? "Good morning, " : "Good evening, ") + name;
}

public sealed class Reception(IGreeter greeter)
{
    public string Welcome(string name) => greeter.Greet(name);
}

public sealed class Counter { public int Value { get; set; } }

public sealed class Report
{
    private readonly string _text;
    public Report(IClock clock) => _text = $"{clock.Now:yyyy-MM-dd}";
    public Report(IClock clock, Counter counter) => _text = $"{clock.Now:yyyy-MM-dd} with counter";
    public string Describe() => _text;
}

public sealed class Ping(Pong pong) { }
public sealed class Pong(Ping ping) { }
